      extra = `  ; ${sub.nombre}/${sub.aridad}`;
      for (let k = 0; k < sub.nUpvalues; k++) { const l = ch.code[i++], idx = ch.code[i++]; extra += ` [${l ? 'local' : 'up'} ${idx}]`; }
