    if (si || !x || typeof x !== 'object') return;
    if (Array.isArray(x)) { x.forEach(ver); return; }
    if (x.tipo === 'Llamada' && x.callee && x.callee.tipo === 'Variable' && NOMBRES.has(x.callee.nombre)) { si = true; return; }
