      if (quitarMedia) { for (let i = 0; i < tamano; i++) m += x[f * salto + i]; m /= tamano; }
      for (let i = 0; i < tamano; i++) d[f * 2 * tamano + 2 * i] = (x[f * salto + i] - m) * w[i];
