    if (doble && c2 === null) vm.error(`«filtrarFrecuencias»: un filtro «${tipo}» necesita dos cortes (desde y hasta)`);
    if (!doble && c2 !== null) vm.error(`«filtrarFrecuencias»: un filtro «${tipo}» lleva un solo corte`);
