  for (;;) {
    pot = pot * Z2 / SS; n += 2n;
    const t = pot / n;
    if (t === 0n) break;
    suma += t;
  }
  let ln = 2n * suma * (1n << BigInt(j));
  ln += BigInt(k) * grLn2Fijo(ww) + BigInt(E) * grLn10Fijo(ww);
